package com.familygrowth.application;import com.familygrowth.domain.Stage3Models.Actor;import com.familygrowth.domain.Stage8Models.ChildSyncSnapshot;import java.time.Clock;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class Stage8Service{private final Stage3Service auth;private final Stage8Store store;private final Clock clock;public Stage8Service(Stage3Service auth,Stage8Store store,Clock clock){this.auth=auth;this.store=store;this.clock=clock;}@Transactional(readOnly=true)public ChildSyncSnapshot snapshot(Actor actor,UUID family,UUID child){auth.requireChildOrParent(actor,family,child);return store.snapshot(family,child,clock.instant());}}
